#include "WaterSimulation.h"
#include "WorldCore/ChunkState.h"
#include "WorldPhaseW3_Event/WorldEventSubsystem.h"
#include "Engine/World.h"
void UWaterSimulation::SimulateChunk(UChunkState* C,float Days){if(!C||Days<=0)return;const int32 Axis=FMath::RoundToInt(FMath::Sqrt((float)C->Cells.Num()));if(Axis<=0)return;if(!FlowSolver)FlowSolver=NewObject<UWaterFlowSolver>(this);UWaterLayer* Layer=NewObject<UWaterLayer>(this);Layer->CellsPerAxis=Axis;Layer->bIsActive=true;int32 Count=0;for(int32 I=0;I<C->Cells.Num();++I){FChunkCell& Cell=C->Cells[I];Cell.Water.Level=Cell.Water.Volume/FMath::Max(0.01f,CellAreaM2);Layer->Cells.Add(I,Cell.Water);if(Cell.Water.Volume>0.001f)++Count;}Layer->RecomputeTotals();if(FlowSolver)FlowSolver->SolveFlow(Layer,Days*86400.0f);for(int32 I=0;I<C->Cells.Num();++I){FChunkCell& Cell=C->Cells[I];const FWaterCell* Water=Layer->Cells.Find(I);if(!Water)continue;const float Old=Cell.Water.Level;Cell.Water=*Water;Cell.Water.Level=Cell.Water.Volume/FMath::Max(0.01f,CellAreaM2);Cell.bHasWater=Cell.Water.Volume>0.001f;if(!FMath::IsNearlyEqual(Old,Cell.Water.Level,0.001f))OnWaterLevelChanged(C,I,Old,Cell.Water.Level);}if(Count>0)BroadcastEventIfNeeded(C,EWorldEventType::WaterLevelChanged,(float)Count);}
void UWaterSimulation::OnWaterLevelChanged(UChunkState* C,int32 I,float Old,float New){if(!C||!C->Cells.IsValidIndex(I))return;FChunkCell& Cell=C->Cells[I];const float D=New-Old;Cell.SoilMoisture=FMath::Clamp(Cell.SoilMoisture+D*0.1f,0.0f,1.0f);FWorldEvent E;E.Type=EWorldEventType::SoilMoistureChanged;E.ChunkCoord=C->Coordinate;E.Magnitude=FMath::Abs(D);E.NumericPayload.Add(TEXT("CellIndex"),(float)I);if(UWorld* W=GetWorld())if(UWorldEventSubsystem* ES=W->GetSubsystem<UWorldEventSubsystem>())ES->BroadcastEvent(E);}
void UWaterSimulation::ApplyRainfall(UChunkState* C,float Mm){if(!C||Mm<=0)return;const float Added=Mm*0.001f*FMath::Max(0.01f,CellAreaM2);for(FChunkCell& Cell:C->Cells){Cell.Water.Volume+=Added;Cell.bHasWater=true;Cell.bIsDirty=true;}C->MarkDirty();}
void UWaterSimulation::BroadcastEventIfNeeded(UChunkState* C,EWorldEventType T,float M){if(!C)return;FWorldEvent E;E.Type=T;E.ChunkCoord=C->Coordinate;E.Magnitude=M;if(UWorld* W=GetWorld())if(UWorldEventSubsystem* ES=W->GetSubsystem<UWorldEventSubsystem>())ES->BroadcastEvent(E);}
